style.css:
@-moz-document domain("pinterest.com"), domain("pinterest.es"), domain("pinterest.com.mx"), domain("pinterest.co"), domain("pinterest.cl"), domain("pinterest.com.ar") {
/* ==========================================================================
       HOT ROD G1 (TRANSFORMERS) - V2 (REFORZADO PARA PINTEREST)
       ========================================================================== */

    /* 1. Sobrescribir las variables globales de color de Pinterest */
    :root,
    html,
    body,
    [data-theme],
    .GestaltTheme {
        --color-background-default: #141112 !important;
        --color-background-elevation-accent: #1F1A1C !important;
        --color-background-elevation-floating: #261C1E !important;
        --color-background-secondary-base: #2B181B !important;
        --color-background-secondary-hover: #3D1E23 !important;
        --color-background-primary-base: #D31A2B !important;
        --color-background-primary-hover: #FF6A00 !important;
        --color-background-shopping: #FF6A00 !important;

        --color-text-default: #F0F3F7 !important;
        --color-text-subtle: #B8C0CC !important;
        --color-text-inverse: #141112 !important;
        --color-text-link: #00C8FF !important;

        --color-border-container: #4A1C22 !important;
        --color-border-default: #FF6A00 !important;

        background-color: #141112 !important;
        color: #F0F3F7 !important;
    }

    /* 2. Forzar fondo oscuro en todos los contenedores blancos por defecto */
    body,
    #__PWS_ROOT__,
    [role="main"],
    [data-test-id="appContent"],
    [data-test-id="homefeed-feed"],
    div[style*="background-color: rgb(255, 255, 255)"],
    div[style*="background-color:#ffffff"],
    div[style*="background-color: white"] {
        background-color: #141112 !important;
    }

    /* 3. Barra superior y barra lateral izquierda (Chasis Rojo Hot Rod + Borde Amarillo) */
    header,
    nav,
    [data-test-id="header-background"],
    [data-test-id="navigation-sidebar"],
    [aria-label="Navegación principal"],
    [aria-label="Primary navigation"] {
        background: linear-gradient(90deg, #8F0A16 0%, #D31A2B 50%, #A8101E 100%) !important;
        border-bottom: 3px solid #FFD200 !important;
        border-right: 2px solid #FF6A00 !important;
        box-shadow: 0 4px 15px rgba(255, 106, 0, 0.35) !important;
    }

    /* 4. Barra de búsqueda (Toma de aire oscura con borde naranja) */
    [data-test-id="search-box-container"],
    [role="combobox"],
    input[type="text"],
    input[aria-label*="Buscar"],
    input[aria-label*="Search"] {
        background-color: #1F1A1C !important;
        color: #FFFFFF !important;
        border: 2px solid #FF6A00 !important;
        border-radius: 10px !important;
    }

    [data-test-id="search-box-container"]:focus-within,
    input[type="text"]:focus {
        border-color: #FFD200 !important;
        box-shadow: 0 0 12px rgba(255, 106, 0, 0.8) !important;
    }

    /* 5. Botones principales (Guardar / Seguir / Crear) con degradado fuego G1 */
    [data-test-id="PinBetterSaveButton"] button,
    [data-test-id="PinBetterSaveButton"] div[role="button"],
    button[aria-label*="Guardar"],
    button[aria-label*="Save"],
    div[style*="background-color: rgb(230, 0, 35)"] {
        background: linear-gradient(135deg, #D31A2B 0%, #FF6A00 60%, #FFD200 100%) !important;
        color: #111111 !important;
        font-weight: 800 !important;
        border: 1px solid #FFFFFF !important;
        box-shadow: 0 0 10px rgba(255, 106, 0, 0.6) !important;
    }

    /* 6. Tarjetas de Pines y hover con brillo de escape */
    [data-test-id="pin"],
    [data-test-id="pinWrapper"] {
        background-color: #1F1A1C !important;
        border: 1px solid #3A2226 !important;
        border-radius: 16px !important;
        transition: all 0.2s ease !important;
    }

    [data-test-id="pin"]:hover,
    [data-test-id="pinWrapper"]:hover {
        border-color: #FFD200 !important;
        box-shadow: 0 0 16px rgba(255, 106, 0, 0.55) !important;
    }

    /* 7. Menús emergentes, notificaciones y modales */
    [role="menu"],
    [role="dialog"],
    [role="listbox"],
    [data-test-id="popover"] {
        background-color: #1F1A1C !important;
        border: 2px solid #D31A2B !important;
        color: #FFFFFF !important;
    }

    /* Hover dentro de menús */
    [role="menuitem"]:hover,
    [role="option"]:hover {
        background-color: #3D1E23 !important;
    }

    /* 8. Textos, enlaces (Azul Óptico) e iconos */
    h1, h2, h3, h4, p, span, div {
        color: #F0F3F7;
    }

    a, a span {
        color: #00C8FF !important;
    }

    a:hover, a:hover span {
        color: #FFD200 !important;
    }

    header svg,
    nav svg {
        color: #FFFFFF !important;
        fill: #FFFFFF !important;
    }

    /* 9. Barra de desplazamiento (Scrollbar) */
    ::-webkit-scrollbar {
        width: 10px !important;
        background: #141112 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(180deg, #D31A2B, #FF6A00, #FFD200) !important;
        border-radius: 5px !important;
    }
}
